var solar1 = ReadDouble("Energy.Solar.Array1.Power_kW");
var solar2 = ReadDouble("Energy.Solar.Array2.Power_kW");
var wind1 = ReadDouble("Energy.Wind.Turbine1.Power_kW");
var wind2 = ReadDouble("Energy.Wind.Turbine2.Power_kW");
var totalGen = solar1 + solar2 + wind1 + wind2;
Write("Energy.Summary.TotalGeneration_kW", Math.Round(totalGen, 1));

var gridImport = ReadDouble("Energy.Grid.Import_kW");
var totalCons = totalGen + gridImport;
Write("Energy.Summary.TotalConsumption_kW", Math.Round(totalCons, 1));

var selfSuff = totalCons > 0 ? (totalGen / totalCons) * 100 : 0;
Write("Energy.Summary.SelfSufficiency_Pct", Math.Round(selfSuff, 1));

var irradiance = ReadDouble("Energy.Solar.Array1.Irradiance_Wm2");
var power = ReadDouble("Energy.Solar.Array1.Power_kW");
var panelArea = 800; // m2
if (irradiance > 0) {
    var eff = (power * 1000) / (irradiance * panelArea) * 100;
    Write("Energy.Solar.Array1.Efficiency_Pct", Math.Round(eff, 1));
}
